const crypto = require('crypto');
const secret = $env.BROKER_LINK_SECRET;
if (!secret) throw new Error('BROKER_LINK_SECRET is not set on the n8n container.');

const inJson = $input.first().json;
const broker = String(inJson.broker || '').trim().toUpperCase();
const sig    = String(inJson.sig || '').trim();

if (!broker || !sig) {
  throw new Error('This link is incomplete. Please open the personal link that was sent to you.');
}
const expected = crypto.createHmac('sha256', secret).update(broker).digest('hex').slice(0, 16);
// Constant-time compare so the signature cannot be guessed byte by byte.
const a = Buffer.from(sig.padEnd(16, ' ').slice(0, 16));
const b = Buffer.from(expected);
if (!crypto.timingSafeEqual(a, b)) {
  throw new Error('This link is not valid. Please open the personal link that was sent to you.');
}
return [{ json: { broker_code: broker } }];

const broker = $('Verify the link signature').first().json.broker_code;
const now = Date.now();

const subs = ($('Load upcoming dates').first().json.results || [])
  .filter(s => s.active && new Date(s.date_from).getTime() > now)
  .sort((a, b) => new Date(a.date_from) - new Date(b.date_from));

if (!subs.length) {
  throw new Error('There are no upcoming events open for registration right now.');
}

const pick = (ml) => !ml ? '' : (ml.en || Object.values(ml)[0] || '');
const label = (s) => {
  const d = new Date(s.date_from);
  const opts = { timeZone: 'Asia/Kolkata' };
  const day  = d.toLocaleDateString('en-IN', { ...opts, day: 'numeric', month: 'short' });
  const time = d.toLocaleTimeString('en-IN', { ...opts, hour: '2-digit', minute: '2-digit' });
  return `${pick(s.name)} — ${day}, ${time}`;
};

// Map question identifiers to ids so the order payload never hardcodes them.
const questions = {};
for (const q of ($('Load questions').first().json.results || [])) {
  questions[q.identifier] = q.id;
}
for (const needed of ['client_phone', 'broker_code', 'consent_given', 'consent_version']) {
  if (!questions[needed]) throw new Error(`The event is missing the "${needed}" question. See runbook 04.`);
}

const CONSENT_TEXT = 'The client has agreed to receive event updates from JSL Wealth on WhatsApp';

const formFields = [
  { fieldLabel: 'Event', fieldType: 'dropdown', requiredField: true,
    fieldOptions: { values: subs.map(s => ({ option: label(s) })) } },
  { fieldLabel: 'Client name', fieldType: 'text', requiredField: true,
    placeholder: 'Full name, as on their ID' },
  { fieldLabel: 'Client mobile', fieldType: 'text', requiredField: true,
    placeholder: '10 digits, for example 9876543210' },
  { fieldLabel: 'Consent', fieldType: 'checkbox', requiredField: true,
    fieldOptions: { values: [{ option: CONSENT_TEXT }] } },
];

return [{ json: {
  formFields,
  broker_code: broker,
  questions,
  consent_version: 'notice-v1-2026-09-21',
  lookup: subs.map(s => ({ id: s.id, label: label(s) })),
}}];

const form  = $input.first().json;
const built = $('Build the registration form').first().json;

const chosen = built.lookup.find(e => e.label === form.Event);
if (!chosen) throw new Error('Please choose an event from the list.');

const name = String(form['Client name'] || '').trim().replace(/\s+/g, ' ');
if (name.length < 3) throw new Error('Please enter the client\'s full name.');

// Accept 9876543210, +91 98765 43210, 09876543210, 919876543210.
let digits = String(form['Client mobile'] || '').replace(/\D/g, '');
if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
if (digits.length === 11 && digits.startsWith('0'))  digits = digits.slice(1);
if (!/^[6-9]\d{9}$/.test(digits)) {
  throw new Error('That does not look like an Indian mobile number. Enter 10 digits starting with 6, 7, 8 or 9.');
}

// n8n returns an unchecked required checkbox as false or an empty array.
const consentRaw = form.Consent;
const consented = Array.isArray(consentRaw) ? consentRaw.length > 0 : Boolean(consentRaw);
if (!consented) throw new Error('The client must agree to receive WhatsApp updates before you can register them.');

const q = built.questions;
return [{ json: {
  subevent: chosen.id,
  event_label: chosen.label,
  attendee_name: name,
  phone_e164: '+91' + digits,
  broker_code: built.broker_code,
  order_payload: {
    status: 'p',
    payment_provider: 'free',
    locale: 'en',
    send_email: false,
    comment: `Registered by broker ${built.broker_code} via the web form`,
    positions: [{
      positionid: 1,
      item: Number($env.PRETIX_ITEM_ID || 1),
      price: '0.00',
      attendee_name: name,
      subevent: chosen.id,
      answers: [
        { question: q.client_phone,    answer: '+91' + digits,        options: [] },
        { question: q.broker_code,     answer: built.broker_code,     options: [] },
        { question: q.consent_given,   answer: 'true',                options: [] },
        { question: q.consent_version, answer: built.consent_version, options: [] },
      ],
    }],
  },
}}];

